quests[37210] = { id = 37210, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aogexon's Fang", progress = "Aogexon is one of the most feared beasts in Nagrand, and one of the largest and most dangerous forest stalkers ever seen!\n\nI've already been approached by a number of a collectors interested in obtaining one of Aogexon's deadly fangs. If you are up for the challenge, Aogexon can sometimes be found lurking in the swamp not far from here.\n\nGood luck!", completion = "Great work, {name}! You've made the swamp a safer place for archaeology and earned us a profit at the same time!" }
quests[37211] = { id = 37211, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bergruu's Horn", progress = "An anonymous collector of valuable fossils and antiques has offered the preservation society a huge cash reward for Bergruu's horn.\n\nA huge reward, {name}... HUGE!", completion = "Wow! I knew Begruu's horn would be big, but I never imagined it would be this massive!\n\nWe're going to have to charge the buyer extra for delivery!" }
quests[37212] = { id = 37212, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Proving Grounds - Damage Bronze" }
