quests[37220] = { id = 37220, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "FLAG - Proving Grounds - Healer Gold" }
quests[37221] = { id = 37221, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dekorhan's Tusk", progress = "Few elekk have lived as long as Dekorhan. Elekk tusks continue to grow throughout the elekk's lifetime.\n\nThis makes Dekorhan's tusks some of the largest and oldest on Draenor.\n\nDo you hear what I hear, {name}? That's the sound of all the gold jingling in our pockets after you bring me Dekorhan's tusk!", completion = "What a find! Great work, {name}!\n\nDekorhan's tusk will be the centerpiece of someone's collection!" }
quests[37222] = { id = 37222, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Direhoof's Hide", progress = "Most talbuk are peaceful creatures that will only attack when they are defending their herd. Not Direhoof though, that talbuk is one of the most aggresively dangerous beasts I've ever encountered... and one of the most magnificent talbuk I've ever seen!\n\nIf you encounter Direhoof while adventuring and live to tell the tale, return to me with the beast's hide and I'll see that you're rewarded!", completion = "I'm not going to lie to you, {name}... I'll be sleeping more soundly at night knowing that Direhoof isn't out there somewhere roaming the wild.\n\nI'll also be sleeping more soundly on the pile of money I'm going to make selling this hide to some rich collector!\n\nCha-ching!" }
quests[37223] = { id = 37223, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gagrog's Skull", progress = "Deep in the forest of northern Nagrand is a giant Gronn known as Gagrog the Brutal. In case you're wondering, he didn't get his name by giving out free hugs... this Gronn is as savage and murderous as they come!\n\nNow look, I'm not telling you to go try and hunt this thing down... that would be suicide... but if by some miracle you fight Gagrog and live, make sure you bring back his skull!", completion = "I can't believe my eyes... you actually took down Gagrog the Brutal? You're tougher than I thought!\n\nGreat work, {name}!" }
quests[37224] = { id = 37224, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mu'gra's Head", progress = "Not far from here is a hippo of unusual size and ferocity known as Mu'gra. I've been contacted by a private collector that would like to acquire Mu'gra's teeth for a special exhibit.\n\nHippo teeth are extremely difficult to extract, and we can't be selling damaged goods so just bring back the entire head, got it?\n\nGood luck!", completion = "Wow! Look at the size of that thing... that's got to be the biggest hippo I've ever seen!\n\nMu'gra was one of the angriest hippos I've ever seen, but she's all smiles now!\n\nGet it? Hippo teeth... smiles... eh, eh?" }
quests[37225] = { id = 37225, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thek'talon's Talon", progress = "Windrocs can be found all over Nagrand, from the highest peaks to the lowest valleys. However, one windroc in particular is extremely elusive and is rarely sighted, it is known to the orcs as Thek'talon.\n\nIf I know anything, it's that people will pay a lot of money for anything that is rare or elusive!", completion = "What's that you got there?\n\n<Gazmolf examines the talon>\n\nHey! That definitely looks like it belonged to Thek'talon, and even if it's not who's to say otherwise? Great work, here's your cut!" }
quests[37226] = { id = 37226, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Xelganak's Stinger", progress = "Xelganak is as deadly as they come, {name}! I don't recommend going after Xelganak unless you love money, adventure, and glory.\n\nXelganak's poison stinger would be an easy sell to the right collector, so if you're up for the challenge I'll make sure you get handsomely rewarded.\n\nJust don't go getting your face melted off like Bozzil, ok?", completion = "Whoa! Careful where you point that stinger!\n\n<Gazmolf examines Xelganak's stinger>\n\nExtraordinary... I've never seen anything like this before. As an archaeologist of the highest caliber, it is an honor to artificially fossilize this item and sell it to the highest bidder.\n\nWell done!" }
quests[37227] = { id = 37227, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Put a Bird on It", description = "{name}! Have you met the peachick you saved the other day?\n\n<Mylune holds up a peachick hatchling, then trills and twitters at it. She gestures to you, says your name, then continues chirping animatedly to the little bird. The two ignore you and engage in a lengthy bird-conversation, long enough to make you feel awkward. Finally the dryad turns her attention back to you.>\n\nDid you hear that? More peachicks are still trapped in the Everbloom! If you don't save them... well, you heard what will happen!", progress = "<Mylune stamps her hooves impatiently.>", completion = "Oh, thank you {name}! You've made a lot of wee baby birds very happy.\n\n\n\n\n\nYou're my favorite {race}!", objectives = "Find a Tiny Peachick Hatchling in The Everbloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37228] = { id = 37228, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fruitful Proposition", description = "The head of just ONE ogre won't be enough to stop the fruit vendor. No, the fruit vendor is wise, they would not put all of their fruit into one basket.\n\nBring me the head of ANOTHER ogre! Ha! Then what will the fruit vendor do? Cry onto their bananas as they rot and fall to the ground.\n\nDESPAIR, FRUIT VENDOR. SO DELICIOUS!", progress = "THE FRUIT VENDOR STANDS NO CHANCE!", completion = "We are one step closer to crushing the fruit vendor's grapes into muddy wine.", objectives = "Collect a Giant Ogre Head from the Bloodmaul Slag Mines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37229] = { id = 37229, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like A Dwarf In A Mine", description = "Baelog and Eric swear there's got to be treasure at the bottom of the mine. Why? Because it's a mine! An' we sure do love rocks that sparkle.\n\nOn our last trip, we were beaten back by huge ogres. Baelog held up the rear, swingin' his sword, while Eric rushed on ahead to try and find a quick exit.\n\nWouldn't you know, in all that excitement, I done lost my shield AGAIN?\n\n<Olaf looks at you imploringly.>", progress = "<Olaf sobs.>", completion = "By the light, that's her! You've done it again, an' I can't thank you enough! We'll try to be more careful next time.", objectives = "Collect Olaf's Shield from the Bloodmaul Slag Mines.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37230] = { id = 37230, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bloody Expensive", description = "Welcome back, commander. The commander is obviously in a great hurry, and certainly the thought of removing their coat or boots or not dripping all over the floor are much too far beyond consideration.\n\nThe commander remembers the acidic solution, yes? Quite effective it was, though one barrel was not enough to remove ALL of the blood stains from the portraits, or the tapestries, or the ceiling.\n\nSurely this must have been the most heroic and viscous battle in recent history.", progress = "Was the commander successful?", completion = "Again, though more barrels were likely available, one will staunchly make do with the single barrel provided, comforted in the knowledge that the commander must deal with the great pressing issues of this land, and does not have time to clean up the mud that that so dutifully follows the commander's heroic allies.", objectives = "Collect a barrel of Horribly Acidic Solution from the Iron Docks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37231] = { id = 37231, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Search Continues", description = "An old deckhand inspected that device you brought us, and thinks it was quite the forgery. This Iron Horde is trying to copy the mechanism, but they don't quite have the technology.\n\nWhen you get right down to it, we're not sure how these primitive beasts got a hold of this kind of tool. Wouldn't be half as good of a sea tale if we knew, ha!\n\nWe've still got a pile of treasure with your name on it, if you can find us the real compass.", progress = "Did you find the compass?", completion = "Let's hope this is the real thing, every time I go through that portal I feel my fur stand on end.", objectives = "Find the Brass Compass at the Iron Docks.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37232] = { id = 37232, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Soulcarver Voss", description = "You! You're the one that found me the blade, correct? I have need of your services again.\n\nThe blade worked wonderfully, allowing me to sever the tormented undead from this world. Their screams were such beautiful music.\n\nHowever, the Soulsever Blade cannot be repaired, as it is partially woven with spirit energy that is drawn upon each time a soul is released. I need another, as there are still dark forces at work in this place, raising spirits and turning them.", progress = "Did you find the blade?", completion = "Yes, yes this is perfect. It is time, little souls, to return to the twisting darkness.\n\n<Lilian cackles madly.>", objectives = "Collect a Soulsever Blade from Auchindoun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37233] = { id = 37233, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vessel of Virtue", description = "Hello, again, commander. This plague yet vexes me, but I shall remain resolute, with the light as my guide.\n\nThe Soulweave Vessel has aided our investigations into the world beyond and the transition from life to death. With more vessels, we may be able to discover the truth behind the bridge between worlds. Perhaps there is a reason why the scourged do not fully make this transition.\n\nAny additional help would be greatly appreciated by the Argent Dawn.", progress = "Did you find anything?", completion = "Once again, though I will need to return to Light's Hope shortly, you have my most sincere thanks.", objectives = "Collect a Soulweave Vessel from Auchindoun.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37234] = { id = 37234, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dark Within", description = "The light... has gone out. I know not why.\n\nI am more troubled now than before. I can find little comfort in the everyday. Each day seems darker than the last.\n\nPlease, bring me another one of the Sun Crystals. Its light is so warm, so comforting.", progress = "Did you find the crystal?", completion = "The warmth comforts me. I thank you.", objectives = "Collect a Sun Crystal in Skyreach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37235] = { id = 37235, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Plea to the Sky", description = "We have, so far, been unsuccessful in our attempts to contact the arakkoa. Each attempt strips the plumage, and we are left with a feather that is tattered and broken.\n\nAviana implores you, commander, to find another plume for her. We do not wish to see our brethren become victim of their own violent nature. All beings of the sky have a place with us, in life or beyond.", progress = "Did you bring a feather?", completion = "We will continue to attempt to parlay with the arakkoa.\n\nAviana's blessing upon you.", objectives = "Collect some Pristine Plumage in Skyreach.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37236] = { id = 37236, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Like Father, Like Son", description = "He's done it again! My son took my knife and yelled something about a 'chromatic hide,' then ran off for the Spire! What would he even do with something like that, wear it around like a cape?\n\nIf it's not too much to ask, would you keep an eye out for the knife? You know, next time you're around Upper Blackrock Spire. Which, hopefully, is soon. VERY soon.", progress = "Where's my knife?", completion = "You've saved it! A little nicked, but that can be fixed. Thanks!", objectives = "Find Pip's Improved Skinner in Blackrock Spire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37237] = { id = 37237, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Hero's Quest is Never Complete", description = "What ho, squire {name}! Since last we spoke, I have heroically approached the gates of Blackrock Spire and nobly intended to end the toothy reign of its dragons.\n\nYet, as I neared the place, my mind drifted to thoughts of my Doloria's fair face, and to my own painfully unsatisfied desires.\n\nMy sword arm fell limp at my side.\n\nI charge THEE then, squire, to go in my stead and search Upper Blackrock Spire. I must know if the dragons still squirm within its corridors.", progress = "Did you find evidence of dragons?", completion = "By the light, they breed like great fiery rabbits! I shall head there presently, to slay no less than THIRTY of the great beasts.\n\nFor Doloria!", objectives = "Collect a Shed Proto-Dragon Claw.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37238] = { id = 37238, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Secrets of Soulbinding", description = "We have reviewed Ner'zhul's notes, which you brought to us previously. Though we are closer to understanding how these warlocks have learned to bind souls and control the undead, the picture is incomplete.\n\nWe will need more pages if we are to see the whole picture. I do not want to experiment with partial information and create an abomination. There are enough of those in Northrend as it is.", progress = "Did you find any of Ner'zhul's notes?", completion = "We are greatful for your aid. I shall retire shortly.", objectives = "Collect a Dark Parchment from the Shadowmoon Burial Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37239] = { id = 37239, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fate of the Fallen", description = "I feel that I can trust you, perhaps. You have, at least, not spoken of my secret to anyone, and for that I thank you.\n\nI have need of your aid again, and in return, I will share some of my own information. I am here, you see, to find an elf by the name of Alleria. She was lost years ago, on Draenor. It is my faint hope that the twisting nether brought her here.\n\nI do not know if such a thing is even possible, but do keep an eye out for any signs of high elves as you travel.", progress = "Did you find anything?", completion = "Another one? How curious.\n\nI may not be much closer to finding her, but these arrows bring some comfort to me, at least.", objectives = "Collect a Silver-Lined Arrow from the Shadowmoon Burial Ground.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37240] = { id = 37240, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Leaf-Reader", description = "Good ta see you again, mon!\n\nDe Cenarion Circle sent Zen'kiki out here ta find some more of dem plants. We not likin' what we be seein' here.\n\nIf ya find any more of dem leaves, bring one on back. Dey can see right through Zen'kiki's tree disguise, even when he plant himself in da ground!\n\nAnd dat make it harder to run!", progress = "Did ya have much luck, mon?", completion = "Thanks, mon. I'm gonna bring this back to the Circle, just as soon as I can figure out how ta fly in da savage winds of dis place.", objectives = "Collect a Strangely-Glowing Frond from Everbloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37241] = { id = 37241, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lessons of the Past", description = "I have returned! You must have known that a world so rich in history could not keep me away for long!\n\n<Lorewalker Cho chuckles, holding his enormous belly.>\n\nI have perhaps been taking part in too many celebratory feasts, now that the Vale has been cleansed. There is so much to celebrate in Pandaria!\n\nShould you find any future evidence of titanic influence on the native species, I will be here, heartily enjoying the roast clefthoof.", progress = "Have you found any signs of the titans here?", completion = "Another excellent find from our most illustrious hero! I will immediately begin transcribing your heroic deeds!", objectives = "Collect an Overgrown Artifact from The Everbloom.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37242] = { id = 37242, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Learning Is Painful", description = "The academy is up and running, in a secret location of course. Maybe it doesn't exist at all?\n\nBy the by, I appear to be running quite dry on sharp, pointy instruments of education.\n\n<Lonika winks at you several times before nudging you sharply in the ribs with her dagger.>", progress = "Did you find me some weapons?", completion = "Once again, you have proven yourself invaluable. Perhaps you would like a teaching job?", objectives = "Collect a Huge Crate of Weapons in Grimrail Depot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37243] = { id = 37243, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "An Axe to Grind", description = "I, Gamon, have cleaved many orc skulls. Yet many of the iron horde remain, full of limbs and blood. I will relieve them of these things!\n\nOr I would, if I had an axe. The last one broke in half in the middle of an orc's ribcage.\n\n<Gamon laughs heartily.>\n\nBring me another, so that I may continue cleaving my way through this land!", progress = "What?", completion = "A mighty blade, but I will wear it out quickly. Orc heads are harder than they look.", objectives = "Find an Iron Limbcleaver in Grimrail Depot.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37244] = { id = 37244, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flamefly Trap", description = "Ol' Winky still hasn't come back! Now I'm gettin' worried.\n\nDo me a favor and get another one of those flameflies from Upper Blackrock Spire. If we get enough of em,' Winky's sure to see the glimmer and come heading on back.\n\nAn then we'll have him right where we want him!", progress = "Did ye get another fly?", completion = "Oi, that's a bright fly! Thank ye, we'll just keep on tryin' until that two-timing ol' Winky comes on home.", objectives = "Collect a Spire Flamefly in Upper Blackrock Spire.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37245] = { id = 37245, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Whispers in the Darkness", description = "If you don't mind, I'm trying VERY hard to prevent all of our worlds from collapsing into the void, AGAIN.\n\nOh, right, you helped me last time, didn't you? Well, you've got great timing. I'm in need of another Gate-Key.\n\nWell? Go on! The infinite horrors of the abyss aren't just going to wait until you've had a nap! Having that many tentacles makes them really antsy.", progress = "You do know that any time you waste talking to me brings us closer to doom, right?", completion = "Perfect, here's a prize for your efforts.\n\nI've got to head out and save everyone now. Again.", objectives = "Find a Void-Gate Key in the Shadowmoon Burial Grounds.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37246] = { id = 37246, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mysterious Fruit Pile" }
