quests[37248] = { id = 37248, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mastering the Menagerie", description = "I'd like you to do some training.  Head out and test your skill against the trainers in Draenor.", objectives = "Defeat the Draenor battle pet trainers.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
