quests[37255] = { id = 37255, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "COLISEUM WINNER FLAG (WEEKLY RESET)" }
quests[37256] = { id = 37256, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "They Came From the Sea", description = "You're looking for Prince Farondis?\n\n<The ghostly elf narrows her eyes warily.>\n\nI can take you to Farondis... but first things first. These naga attacked suddenly. They take orders from one called Zarrin, in the low hills to the west.\n\nHelp me take Zarrin's head, and you'll have my ear.", progress = "<The nightwatcher looks at you expectantly.>", completion = "<Idri stares at the ugly head.>\n\nYes, that's him.", objectives = "Obtain the Head of Fathom-Commander Zarrin, and slay 8 of his naga troops.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37257] = { id = 37257, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Our Very Bones", description = "You seek the Tidestone of Golganneth?\n\nYes, I know where it lies. It is in a place to which I prefer not to return.\n\nYou may be of use to me. In the midst of this naga attack, those horrid fish-men flopped their way onto my lands and raided our graveyards. They steal the bones of our ancestors, and indeed, the very bones of my people.\n\nHelp me bring some solace to my people. Then I shall tell you more about the Tidestone.", progress = "My people may not care much for me, but that will not stop me from caring for them.", completion = "Our bones are all we have left of an existence we left behind a long time ago.\n\n<The prince stares intently into your eyes.>\n\nStay with me, {class}. I will help you find your Tidestone.", objectives = "Obtain 55 Pilfered Night Elf Bones.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37259] = { id = 37259, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Teron'gor", description = "{name}, I need you to assemble a fearless group and lead them into the depths of Auchindoun. Activate the Challenger's Orb, and cleanse Auchindoun of Teon'gor's evil presence.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", completion = "{name}, you've done a great service. May the souls of Auchindoun remain at peace with the threat of Teron'gor eliminated.", objectives = "Complete the Auchindoun Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37260] = { id = 37260, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Gug'rokk", description = "{name}, I need you to assemble a formidable group and head into the depths of the Bloodmaul Slag Mines. Activate the Challenger's Orb, and free the miners of Gug'rokk's tyrannical rule.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", completion = "{name}, you've done a great service. The families of the rescued miners will never be able to thank you enough for eliminating Gug'rokk and his slavers.", objectives = "Complete the Bloodmaul Slag Mines Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37261] = { id = 37261, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Skylord Tovra", description = "{name}, I need you to assemble an elite group to infiltrate the Grimrail Depot. Activate the Challenger's Orb, and make your way to the Grimrail and put an end to it and Skylord Tovra's air support.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", completion = "{name}, you've done a great service. Eliminating Skylord Tovra's rylak escorts and disrupting the Grimrail will save an innumerable amount of lives.", objectives = "Complete the Grimrail Depot Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37262] = { id = 37262, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Skullok, Son of Gruul", description = "{name}, I need you to assemble a hardy group to breach the Iron Docks. Activate the Challenger's Orb, and put a stop to the Iron Horde's training facility and their subjugation of Draenor's mightiest, including Skullok, Son of Gruul.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", completion = "{name}, you've done a great service. Taking down one of Draenor's great giants is regrettable, but letting Skullok, Son of Gruul, remain a tool of the Iron Horde would have led to great distruction.", objectives = "Complete the Iron Docks Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37263] = { id = 37263, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Ner'zhul", description = "{name}, I need you to assemble a resolute group of warriors and venture into the Shadowmoon Burial Grounds. Activate the Challenger's Orb, and put a stop to Ner'zhul's communion with the void before he takes all of Draenor with him.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", completion = "{name}, you've done a great service. Putting an end to Ner'zhul and his deathly rituals will allow many to sleep better at night.", objectives = "Complete the Shadowmoon Burial Grounds Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37264] = { id = 37264, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: High Sage Viryx", description = "{name}, I need you to assemble a determined group of adventures and venture into Skyreach. Activate the Challenger's Orb, reach the summit and put an end to High Sage Viryx and her super weapon.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", completion = "{name}, you've done a great service. If not for you, all of Draenor may have withered under High Sage Viryx's rule.", objectives = "Complete the Skyreach Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37265] = { id = 37265, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Yalnu", description = "{name}, I need you to assemble a resolute group of adventures and journey in to The Everbloom. Activate the Challenger's Orb, penetrate the depths of The Everbloom and put a stop to Yalnu and his ambitions.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", completion = "{name}, you've done a great service. Your efforts to stop Yalnu may not only have saved our outpost but all of Azeroth as well.", objectives = "Complete The Everbloom Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37266] = { id = 37266, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Warlord Zaela", description = "{name}, I need you to assemble a group of stalwart adventures and journey back to Azeroth and Upper Blackrock Spire. Activate the Challenger's Orb, enter the old home of the Blackrock clan and defeat the Ironmarch Vanguard and their new ally, Warlord Zaela.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", completion = "{name}, you've done a great service. Defeating the Ironmarch Vanguard at Upper Blackrockspire is a major blow to the Iron Horde and Azeroth can rest a bit more knowing Warlord Zaela's bid for revenge has been permanently dealt with.", objectives = "Complete the Upper Blackrock Spire Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37268] = { id = 37268, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowmoon Invasion! BETA", description = "Scouts report that the Shadowmoon Clan is buzzing like a kicked hornets' nest. Time again to earn our pay, Commander?", progress = "Commander, we'll assemble the troops at your command.", completion = "Nothing like a little righteous bloodshed, to shake the chill from these old bones.", objectives = "Repel the Shadowmoon Clan invasion of your garrison.\n\n(Speak with Sergeant Crowler again to begin)", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37269] = { id = 37269, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowmoon Invasion! BETA", description = "Scouts say the Shadowmoon Clan looms close, ready with their necromancy. If I die and rise again, Commander, finish me quickly. I don't want to be a ghoul.", completion = "You were a blaze amongst our foes, Commander. It looks like we'll see another dawn in Draenor.", objectives = "Repel the Shadowmoon invasion of your garrison.\n\n(Speak with Sergeant Grimjaw again to begin)", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37270] = { id = 37270, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alchemy Experiment", objectives = "I've been experimenting again today, and I've come up with some potion formulations that might suit you, commander. Would you like to try one?", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37271] = { id = 37271, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Teron'gor", description = "{name}, I need you to assemble a fearless group and lead them into the depths of Auchindoun. Activate the Challenger's Orb, and cleanse Auchindoun of Teon'gor's evil presence.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", completion = "{name}, you've done a great service. May the souls of Auchindoun remain at peace with the threat of Teron'gor eliminated.", objectives = "Complete the Auchindoun Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37272] = { id = 37272, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Gug'rokk", description = "{name}, I need you to assemble a formidable group and head into the depths of the Bloodmaul Slag Mines. Activate the Challenger's Orb, and free the miners of Gug'rokk's tyrannical rule.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", completion = "{name}, you've done a great service. The families of the rescued miners will never be able to thank you enough for eliminating Gug'rokk and his slavers.", objectives = "Complete the Bloodmaul Slag Mines Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37273] = { id = 37273, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Skylord Tovra", description = "{name}, I need you to assemble an elite group to infiltrate the Grimrail Depot. Activate the Challenger's Orb, and make your way to the Grimrail and put an end to it and Skylord Tovra's air support.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", completion = "{name}, you've done a great service. Eliminating Skylord Tovra's rylak escorts and disrupting the Grimrail will save an innumerable amount of lives.", objectives = "Complete the Grimrail Depot Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37274] = { id = 37274, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Skullok, Son of Gruul", description = "{name}, I need you to assemble a hardy group to breach the Iron Docks. Activate the Challenger's Orb, and put a stop to the Iron Horde's training facility and their subjugation of Draenor's mightiest, including Skullok, Son of Gruul.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", completion = "{name}, you've done a great service. Taking down one of Draenor's great giants is regrettable, but letting Skullok, Son of Gruul, remain a tool of the Iron Horde would have led to great distruction.", objectives = "Complete the Iron Docks Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37275] = { id = 37275, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Ner'zhul", description = "{name}, I need you to assemble a resolute group of warriors and venture into the Shadowmoon Burial Grounds. Activate the Challenger's Orb, and put a stop to Ner'zhul's communion with the void before he takes all of Draenor with him.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", completion = "{name}, you've done a great service. Putting an end to Ner'zhul and his deathly rituals will allow many to sleep better at night.", objectives = "Complete the Shadowmoon Burial Grounds Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37276] = { id = 37276, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standing United", objectives = "The Shattered Hand and their allies are dangerous, commander. No offense, but I don't trust your standing forces to keep a future assassin from slipping in unnoticed.\n\nI would like to volunteer myself to join your forces so I can keep a close watch on enemy movements. We cannot risk your untimely death - too much rests on your shoulders.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37277] = { id = 37277, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: High Sage Viryx", description = "{name}, I need you to assemble a determined group of adventures and venture into Skyreach. Activate the Challenger's Orb, reach the summit and put an end to High Sage Viryx and her super weapon.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", completion = "{name}, you've done a great service. If not for you, all of Draenor may have withered under High Sage Viryx's rule.", objectives = "Complete the Skyreach Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37278] = { id = 37278, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Yalnu", description = "{name}, I need you to assemble a resolute group of adventures and journey in to The Everbloom. Activate the Challenger's Orb, penetrate the depths of The Everbloom and put a stop to Yalnu and his ambitions.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", completion = "{name}, you've done a great service. Your efforts to stop Yalnu may not only have saved our outpost but all of Azeroth as well.", objectives = "Complete The Everbloom Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37279] = { id = 37279, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Worthy Challenge: Warlord Zaela", description = "{name}, I need you to assemble a group of stalwart adventures and journey back to Azeroth and Upper Blackrock Spire. Activate the Challenger's Orb, enter the old home of the Blackrock clan and defeat the Ironmarch Vanguard and their new ally, Warlord Zaela.\n\nReturn to me when you've completed this challenge and I shall reward you handsomely.", completion = "{name}, you've done a great service. Defeating the Ironmarch Vanguard at Upper Blackrockspire is a major blow to the Iron Horde and Azeroth can rest a bit more knowing Warlord Zaela's bid for revenge has been permanently dealt with.", objectives = "Complete the Upper Blackrock Spire Challenge Mode.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37280] = { id = 37280, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Snarlpaw Ledge" }
quests[37281] = { id = 37281, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Standing United", objectives = "I mean nae offense, commander, but I don't trust yer forces tae keep ya safe from a Shattered Hand assassination attempt on yer life.\n\nIf it's agreeable to ye, I'd like tae join yer garrison and keep a watch on the scoundrels.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37282] = { id = 37282, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "COLISEUM WINNER FLAG (MONUMENT FLAG-NO RESET)" }
quests[37283] = { id = 37283, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "COLISEUM LOSER FLAG (DAILY RESET)" }
quests[37284] = { id = 37284, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Da Big Score", description = "I know, I know. I be givin' ya these for ya treasures, but now I be wantin' dem back. It be complicated, mon. Do ya want da gold or not?", progress = "So you've got them?", completion = "Oh, ya got dem for me? Excellent. Here's ya money.", objectives = "Obtain Dingy Iron Coins for Griftah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37285] = { id = 37285, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "If You're Sure", description = "You sure be collectin' a lot of treasures. Dey will be worth more next week, but I can take 'em off your hands.", progress = "Here you go.", completion = "Here ya go! Instant gratification's da best gratification!", objectives = "Give surplus Dingy Iron Coins to Griftah.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37286] = { id = 37286, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Bloodshed Never Ends", description = "You are insatiable, gladiator! Let none doubt your voracious appetite for destruction and death!\n\nImperator Mar'gok will be very pleased to see you battling upon the arena floor of the Coliseum once more!\n\nAs before, I will accept nothing less than 100 lives!\n\nKill or be killed, gladiator!", completion = "To the victor go the spoils! All hail {name}!", objectives = "Kill 100 Gladiators at the Coliseum in Highmaul.\n\nYou may access the Coliseum by talking to Kharg at Highmaul or Boneslag at your Gladiator's Sanctum.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37287] = { id = 37287, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Cleaning House", description = "Not long ago, a new recruit showed up by the name o' Jacob Anders. He's been trouble since he got here, always drinkin' and pickin' fights, but he crossed the line this time.\n\nOne o' our patrols spotted him tradin' intel with the Horde - he's a traitor, commander! I thought ye would want tae deal with him personally.\n\nHe was out drinkin' by the water last time I saw him, and I'd bet me pappy's beard he's still there.", completion = "I think ye did the right thing, commander.", objectives = "Deal with Jacob Anders at Southport.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37288] = { id = 37288, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Resources in Ashran", description = "Bodrick has mentioned to me that you have acquired some interesting construction notes in your forays out there. A construction guide or assembly notes perhaps?\n\nYou should speak with Kinkade Jacobs in Stormshield. She is willing to exchange finished blueprints for such things.", completion = "Oh you have some blueprint texts for me? That's great!\n\nLet's do some business!", objectives = "Speak with Kinkade Jacobs at Stormshield in Ashran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37289] = { id = 37289, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Shadowmoon Invasion!", description = "Your arrival couldn't be more timely, commander.\n\nShadowmoon raiders have been spotted closing in on the garrison.\n\nYou repelled their advances at Teluuna Observatory, and created chaos at Shaz'gul.\n\nNow, they surely seek retribution. They will throw everything they have at us.\n\nI have the entire garrison on high alert. Are you ready to face them?", progress = "Time to shine a light on these shadows!", completion = "I don't think they were ready for that. The Shadowmoon will think twice before attacking us again.", objectives = "Repel the Shadowmoon clan invasion of your garrison.\n\n(Speak with Sergeant Crowler again to begin)", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37290] = { id = 37290, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Upgrades in Ashran", description = "You got some construction guides or assembly notes on ya? Oh man that's good news!\n\nI know this guy in Ashran, goes by Torgg Flexington. He's got finished blueprints we need!\n\nGo talk to this guy and bring back some good stuff for us to build, ok?", completion = "Oh YEAH buddy! We can work something out. I got plenty of stuff for you to buy!", objectives = "Speak with Torgg Flexington at Warspear in Ashran.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37291] = { id = 37291, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thunderlord Invasion!", description = "Your timing could not have been better.\n\nYour scouts have reported the approach of a large Thunderlord army.\n\nMy clan can ride out and assist in severing their reinforcements, but you will need to see to the defense of your fort against the bulk of their forces.\n\nSergeant Grimjaw awaits your command.", progress = "The Frostwolves stand ready.", completion = "Well fought, commander. Now to strike back before the Thunderlord can recover.", objectives = "Repel the Thunderlord invasion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37292] = { id = 37292, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not In Your Army", description = "Your men caught one of da new recruits,  talking with da alliance behind your back. She be a traitor, boss-mon! She be a danger to everything you've worked so hard for.\n\nWe have a wyvern ready to be takin' her to your garrison for proper punishment. I thought you would be wantin' to deal with da scoundrel personally.\n\nI last be seein' her on the back road out of Axefall.", progress = "Is da traitor ready to leave, commander?", completion = "You be makin' the right call, commander. There be no room for her kind in your ranks.", objectives = "Deal with Rorka at Axefall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37293] = { id = 37293, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Clearing the Mist", description = "<The troll's skin looks pale. Beads of sweat dot his brow.>\n\nI know you owe me nouting, but if you be willin' ta help me, I have a favor to ask.\n\nTa da north, dere be da creature dat is da cause a' dis poisonous mist.\n\nOnly da heart a' dis beast has da power ta neutralize da toxins in my body.\n\nYa may have ta kill some a dose crawlers while you're at it.\n\nIf ya feel weak from da poison, eat some a dose glowing mushrooms ta counter da effects.", progress = "I ain't feelin' so good.", completion = "Yes! Dat be da heart! You did it...", objectives = "Kill 8 Cerulean Crawlers and collect the Overgrown Heart.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37294] = { id = 37294, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "COLISEUM BOOBY PRIZE FLAG (DAILY RESET)" }
quests[37295] = { id = 37295, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Rylai Crestfall" }
quests[37296] = { id = 37296, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Lack of Wasps", description = "The stings! These cursed wasps drone day and night and their constant aggression taxes me so.\n\nI shall do nothing about your offer until these nuisances are dealt with.", progress = "Wasps are truly despicable things.", completion = "Perhaps my rituals will be undisturbed for a few nights at least. Your offer is intriguing and I think we can come to an agreement.", objectives = "Kill 8 Widow Wasps.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37297] = { id = 37297, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kill Jeron Emberfall" }
quests[37298] = { id = 37298, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonus Objective: Kill Warspear Priests" }
quests[37299] = { id = 37299, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bonus Objective: Kill Stormshield Priests" }
quests[37300] = { id = 37300, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drafting Table Interact" }
quests[37301] = { id = 37301, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armory" }
quests[37302] = { id = 37302, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mage Tower" }
quests[37303] = { id = 37303, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mage Tower" }
quests[37304] = { id = 37304, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Armory" }
quests[37305] = { id = 37305, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bronze Victory", progress = "Surrounded as we are, we cannot be weak. We must win every battle, and win them decisively.", completion = "With every victory, or claim here grows more strong." }
quests[37306] = { id = 37306, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Silver Victory", progress = "The harder we beat our enemies, the less quickly they'll return.", completion = "The was a good fight, Commander. It might give me time to clean my sword.\n\nAnd honor our fallen." }
quests[37307] = { id = 37307, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gold Victory", progress = "The stronger our enemies, the more soundly we must beat them. With so much at stake, a single weak blow could prove disastrous.\n\nLead us to great victory, Commander.", completion = "A complete victory! Draenor denizens will mewl for weeks as they lick their wounds, in whatever dark places they live." }
quests[37308] = { id = 37308, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garrison Invasion - Reward Tracker - Bronze" }
