quests[37317] = { id = 37317, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Talon King Ikiss" }
quests[37318] = { id = 37318, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Dead Do Not Forget...", description = "Many years ago my family and I were slain in this very spot.\n\nThe saberon you see around you are descended from the tribe that murdered my village. Long have I waited, here in this forgotten place, to see justice brought to the saberon for their crimes.\n\nThe Snarlpaw chief is a boneseer, a saberon who divines the future using the remains of the dead.\n\nCollect the ancient skulls of the Snarlpaw ancestors and place them in the boneseer's cauldron.\n\nLet their own bones fill their cauldron for once!", progress = "<The cauldron bubbles and boils.>", completion = "<The boiling cauldron gasps and spurts boiling liquid with each skull that is plunged into the pot.>\n\n<As the last of the skulls is submerged within the bubbling cauldron, you feel the sharp nip of a ghostly breeze upon your skin.>", objectives = "Place 10 Ancient Snarlpaw Skulls in the Boneseer's Cauldron.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37319] = { id = 37319, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jewelcrafting Special Order: Wedding Bands", description = "We've been asked to craft a pair of wedding bands. The clients requested that they be made by you.", progress = "Do you plan to fill the order? We can afford to refuse the work, of course, but it's a good offer.", completion = "These are beautiful. The bride and groom will be well pleased.", objectives = "Craft two Glowing Blackrock Bands. The secondary stats do not matter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37320] = { id = 37320, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jewelcrafting Special Order: A Fine Choker", description = "We have a request for a fine necklace. The client wants to give it to an old enemy, to end the conflict. She didn't specify a design, but I think I heard her mumbling under her breath about a choker. \n\nOh, and she asks that the chain be \"extra sturdy\".", progress = "Do you plan to fill the order? We can afford to refuse the work, of course, but it's a good offer.", completion = "Wonderful. The client was just talking about how she couldn't wait to put it around her rival's neck. I'm sure they won't be in conflict anymore after this gift.", objectives = "Craft a Whispering Iron Choker. The secondary stats do not matter.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37321] = { id = 37321, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jewelcrafting Special Order: A Yellow Brighter Than Gold", description = "We've been commissioned to make a gold bracelet, set with a taladite crystal \"even brighter than gold\". I can handle the metal work, but the crystal isn't something I can do.", progress = "Do you plan to fill the order? We can afford to refuse the work, of course, but it's a good offer.", completion = "This is beautiful.", objectives = "Craft a Critical Strike Taladite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37322] = { id = 37322, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Prophet's Final Message", description = "This unassuming iridescent crystal contains some of the final thoughts of Great Prophet Velen, created sometime in the hours before he confronted Ner'zhul.\n\nDeliver the crystal to Prophet Velen's Memorial beneath the Coliseum of Light near Karabor to hear his final message.", progress = "The arcanum hums in your hand as you get close to the memorial.", completion = "The shrine has dozens of niches where the Prophet's followers have placed their own memory crystals, mourning the great leader's sacrifice. You slide the crystal into an empty socket and the memorial comes to life...", objectives = "Deliver the Prophet's Arcanum to Prophet Velen's Memorial beneath the Coliseum of Light in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37323] = { id = 37323, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jewelcrafting Special Order: Blue the Shade of Sky and Sea", description = "The client wants a pair of silver earrings, set with blue crystals to match her eyes. The metal work is simple enough, but I don't know how to create such a shade of taladite.", progress = "Do you plan to fill the order? We can afford to refuse the work, of course, but it's a good offer.", completion = "These are perfect. I almost feel like my settings aren't worthy of such gems.", objectives = "Craft two Haste Taladite.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37324] = { id = 37324, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Stock: Blackrock Ore", description = "Our latest bracelet design is selling like mad, but we are completely out of the blackrock to make them.", progress = "Unless we get more blackrock ore, we will not be able to fill the orders.", completion = "Thank you.", objectives = "Obtain twenty Blackrock Ore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37325] = { id = 37325, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Out of Stock: True Iron Ore", description = "It seems our little boutique is gaining a reputation.  We use true iron in all our designs, and guess what: we're out!", progress = "We are fortunate that our jewelry is so popular, but we won't be able to make more without any true iron.", completion = "We are back in business!", objectives = "Obtain twenty True Iron Ore.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37326] = { id = 37326, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befriending the Locals", description = "We need allies desperately if we want a chance at surviving until tomorrow. We've made contact with one of the outcast arakkoa, but he refused to discuss alliances without speaking to you first.\n\nHe called himself Dusk-Seer Irrizar. You should speak with him, commander.\n\nYou can find him just southwest of Veil Terokk.", completion = "Ah, so you are the one your people spoke of so highly. We may discuss an alliance, but first...", objectives = "Speak to Dusk-Seer Irizzar near Veil Terokk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37327] = { id = 37327, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Befriending the Locals", description = "Commander, I believe it best for the safety of this outpost if we secure an ally. We've made contact with one of the outcast arakkoa, but he refused to make any promises of alliance without speaking to you first.\n\nHe called himself Dusk-Seer Irrizar. Could you go speak with him, commander?\n\nYou can find him just southwest of Veil Terokk.", completion = "Ah, so you are the one your people spoke of so highly. We may discuss an alliance, but first...", objectives = "Speak to Dusk-Seer Irizzar near Veil Terokk.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37328] = { id = 37328, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Here, Not Now", description = "I will travel to your people to make arrangements soon.\n\nFor now, begone. Leave me in peace.", completion = "Excellent. We have more immediate concerns to deal with until he visits.\n\nDark Ranger Velonara requires your immediate attention, sir.", objectives = "Speak to Taskmaster Gornek at Axefall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37329] = { id = 37329, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Here, Not Now", description = "I will travel to your people to make arrangements soon.\n\nFor now, begone. Leave me in peace.", completion = "Excellent. We have more immediate concerns to deal with until he visits.\n\nHulda Shadowblade requires your immediate attention, sir.", objectives = "Speak to Lieutenant Willem at Southport.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37330] = { id = 37330, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Here, Not Now", description = "I will travel to your people to make arrangements soon.\n\nFor now, begone. Leave me in peace.", completion = "Well done, commander.", objectives = "Speak to Taskmaster Gornek at Axefall.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37331] = { id = 37331, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Not Here, Not Now", description = "I will travel to your people to make arrangements soon.\n\nFor now, begone. Leave me in peace.", completion = "Well done, sir.", objectives = "Speak to Lieutenant Willem at Southport.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37332] = { id = 37332, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fungal Bundle", description = "The umbraspore giant you killed seemed immune to the volatile spores in the area. Perhaps the odd growths you found all over its body contribute to its immunity. You grab a big, disgusting fungal lump in order to give it to the rangari for study.", progress = "What did you find, {class}?", completion = "Oh - you were attacked by an Umbraspore Giant? They're very dangerous - you were brave to face one down!\n\nThis growth you found doesn't seem to be part of the giant. It's almost like another organism living in symbiosis. We'll have to study this more closely and see what benefit it conveys to the host.\n\nThank you, {name}. Outstanding work!", objectives = "Take the Curious Growth to Rangari Sheera at the Rangari Enclave in Shadowmoon Valley.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37333] = { id = 37333, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "LFGDungeons - Draenor - Heroic Random - 1st" }
