quests[37416] = { id = 37416, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feast of the Spires", description = "Boss-mon, I prepared a great feast for you right over dere. You should be havin' a bite or two before you be goin' out for da day.\n\nTrust me, you will feel much betta if you do!", sourceObjective = "Eat a Feast of the Spires at Axefall.", sourceObjectiveStatus = "unverified-source-field" }
quests[37417] = { id = 37417, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Feast of the Spires", description = "Commander, I prepared a great feast for ye right over there. You should be have a bite o' two before you be go out fer the day.\n\nTrust me, it's good fer ya!", sourceObjective = "Eat a Feast of the Spires at Southport.", sourceObjectiveStatus = "unverified-source-field" }
quests[37418] = { id = 37418, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fully Armed and Operational", description = "Commander! Great news! Now that the workshop is fully armed and operational, we can start cranking out siege weapons just as soon as we have the resources.\n\nThe Overcharged Demolisher is the pinnacle of goblin engineering, if I do say so myself. It's more powerful than your average demolisher, and you can use it almost anywhere! The only limit is the amount of fuel we're able to pack into the chasis.\n\nAs soon as you're ready to begin production, just bring us some resources and place a work order!", completion = "Can't wait to get this thing up and running for you, commander!\n\nCheck back in tomorrow, and be sure to wear your blast goggles!", objectives = "Place a Work Order at your Garrison's Workshop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37420] = { id = 37420, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fully Armed and Operational", description = "Commander! Great news! Now that the workshop is fully armed and operational, we can start cranking out siege weapons just as soon as we have the resources.\n\nThe Overcharged Siege Engine is the pinnacle of gnomish  engineering, if I do say so myself. It's more powerful than your average siege engine and you can use it almost anywhere! The only limit is the amount of fuel we're able to pack into the chasis.\n\nAs soon as you're ready to begin production, just bring us some resources and place a work order!", progress = "We're going to need resources if you want us to create a siege weapon!", completion = "Can't wait to get this thing up and running for you, commander!\n\nCheck back in tomorrow, and be sure to wear your blast goggles!", objectives = "Place a Work Order at your Garrison's Workshop.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
