quests[37432] = { id = 37432, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Tracking Quest" }
quests[37433] = { id = 37433, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Grounds", description = "Greetings commander.\n\nWord of your exploits has made its way back to Trial Master Rotun, and he has humbly requested to see your prowess in person. Fighting in his proving grounds would be an excellent way to spread your reputation to the farthest reaches of the Alliance, and beyond.\n\nIf you're interested in proving yourself, talk to me to enter Trial Master Rotun's Proving Grounds.", progress = "Have you completed your challenge?", completion = "Congratulations, commander. You have survived Rotun's trial and proven yourself powerful indeed. \n\nHere, take this weapon, that you may further dominate your foes in battle!", objectives = "Speak with Lieutenant Thorn to enter the Proving Grounds, and then complete a Bronze trial.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37434] = { id = 37434, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Proving Grounds", description = "Hail commander.\n\nWord of your exploits has made its way back to Trial Master Rotun, and he has requested to see your prowess in person. Fighting in his proving grounds would be an excellent way to spread your reputation to the farthest reaches of the Horde, and beyond.\n\nIf you're interested in proving yourself, talk to me to enter Trial Master Rotun's Proving Grounds.", progress = "Have you completed your challenge?", completion = "Congratulations, commander. You have survived the trial of Trial Master Rotun and proven yourself powerful indeed. \n\nHere, take this weapon that you may futher dominate your foes in battle!", objectives = "Speak with Warmaster Zog in your garrison to enter the Proving Grounds, and then complete a Bronze trial.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37435] = { id = 37435, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nagrand - Treasure 084 - Spirit Coffer" }
quests[37439] = { id = 37439, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Thirst Unending", description = "If there is only one lesson you deign to remember from your time on Sunstrider Isle, let it be this - control your thirst for magic.  It is a thirst unending, {name} - what you absorb must be controlled and released via Arcane Torrent.  Failure is to become one of the Wretched... hopelessly addicted and insane.\n\nSeek out a mana wyrm and unleash your Arcane Torrent upon it.  Learn to master your power. When you have sufficiently released an Arcane Torrent, return to me.", progress = "It is not an option or a choice... you must quench your magical thirst.  To fail in this is to fail as a {race}.  Those who thought they could control their needs without tutoring now find themselves as one of the Wretched.\n\nYou do NOT want to end up as an insane addict.  Believe me.", completion = "You've done well today, {name}.  Your willingness to learn shows that you may very well rise above the unyielding cravings you must endure as a {race}.\n\nRest not on your laurels, young one, but instead seek to master what you have learned.  Only through diligence will we as a race survive.\n\nTake this - it may be of some use to you.  Go now, and bring glory once more to our people.", objectives = "Use your Arcane Torrent racial ability on a Mana Wyrm, then return to Arcanist Helion.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37440] = { id = 37440, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Fistful of Slivers", description = "It's a shame that we've lost control of many of the creatures here on the island.  This was once a tranquil place of study and research.  Now it's all we can do to keep from being attacked by our own creations!\n\nI'm going to offer you a chance to receive a magical boon in exchange for some collecting work on your part.  Bring me a stack of arcane slivers that are found on the mana-using creatures of Sunstrider Isle, and I will cast a spell on you that should aid your adventures on the isle.", progress = "Many of the creatures here on the isle were at one point bound into non-aggression and complacency by our magical skills.  When the Scourge destroyed the Sunwell, our hold over these creatures shattered.  Arcane slivers are the remnants of the control we once had, and as such might be usable in fashioning a new device to aid us in regaining their control.\n\nBetter still, perhaps the slivers could be used to see what malaise the isle truly suffers under...", completion = "Splendid - these will do nicely.  I've been doing quite a bit of thinking on the current malaise Sunstrider Isle suffers under.  One possible course of action I had pondered was to collect these arcane slivers from the beasts on the isle.  In doing so, they could be experimented on; this would provide a potential source of culpability.\n\nAnyway, I will tend to the research.  Allow me to place this incantation on you.  I believe you'll make good use of it!", objectives = "Collect 6 Arcane Slivers from any creature on the isle that uses mana, and then return to Arcanist Ithanas on Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37441] = { id = 37441, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solanian's Belongings", description = "With all the chaos happening here at the Sunspire, I haven't had a chance to collect my belongings I've left outside at various places on the isle.  I must maintain my vigil over the Sunwell here, so I'll ask you to collect them in my stead.\n\nI need my scrying orb, my scroll of Scourge magic, and my journal.  Use this satchel for some extra space, as my things are rather bulky.  Return them to me and I'll give you a little something - you know, for the effort; you can keep the satchel as well!", objectives = "Collect Well Watcher Solanian's Scrying Orb, his Scroll of Scourge Magic, and his Journal. They are found on Sunstrider Isle by the pond, the fountain, and one of the Burning Crystals. Return them to the Well Watcher at the Sunspire on Sunstrider Isle when you've collected them all.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37442] = { id = 37442, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Shrine of Dath'Remar", description = "Day after day I stand here, watching, waiting.  I've been accused of dwelling too much on our past, while my eyes look to the horizon.  But it is my firm belief that each visitor to this island should honor those who have sacrificed all so that they may continue to do so.\n\nDath'Remar Sunstrider was our first king.  He led us here from Kalimdor through the Maelstrom.\n\nSeek out his shrine to the west and do not return to me until you have read the plaque upon it in his honor.", completion = "Ah, {name} - thank you for sharing your experience at the Shrine of Dath'Remar.  First off, you should be commended for your sense of duty and respect - it will serve you well not only here, but in all of Azeroth as well.\n\nAs for the odd sensation, it is no doubt a contributing part of the taint that has befallen Sunstrider Isle.  We shall keep an eye on it; thank you for alerting us to it!", objectives = "Read the plaque on the Shrine of Dath'Remar and then return to Well Watcher Solanian at the Sunspire on Sunstrider Isle.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37443] = { id = 37443, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Solanian's Belongings", description = "With all the chaos happening here at the Sunspire, I haven't had a chance to collect my belongings I've left outside at various places on the isle.  I must maintain my vigil over the Sunwell here, so I'll ask you to collect them in my stead.\n\nI need my scrying orb, my scroll of Scourge magic, and my journal.  Use this satchel for some extra space, as my things are rather bulky.  Return them to me and I'll give you a little something - you know, for the effort; you can keep the satchel as well!", progress = "Have you had a chance to find my belongings?  Once we reassert our dominance over Sunstrider Isle, I will need them in my work.  For now though, I must maintain my watch over the Sunwell... or what remains of it.", completion = "Well done - I knew you'd be perfect for the task.  Once it's safe to make use of our outdoor facilities on the isle, I'll be putting these things to good use.\n\nLike I mentioned, please feel free to keep the satchel.  Also, you may find this piece of armor to be useful.  Consider it ample compensation for a simple task performed dutifully!", objectives = "Collect Well Watcher Solanian's Scrying Orb, his Scroll of Scourge Magic, and his Journal. They are found on Sunstrider Isle by the pond, the fountain, and one of the Burning Crystals. Return them to the Well Watcher at the Sunspire on Sunstrider Isle when you've collected them all.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37444] = { id = 37444, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Inoculation", description = "Zhanaa needs our help to salvage parts from the Exodar.  Taerix prepared an inoculum that can be given to the Nestlewood owlkin that live in the area of a lot of the salvage.\n\nJust get close to the unaffected ones and use the crystal on them.  Unfortunately, you'll have to kill the others.  You'll find the owlkin at Nestlewood Thicket and Nestlewood Hills to the southeast.", progress = "The more we can do to clear up Nestlewood, the faster Zhanaa can get back to work.", completion = "With many of the owlkin now inoculated, we can focus on getting out of here and not have to worry about wiping out the owlkin population in the area.\n\nHere, choose from these.  You've done good work, and you deserve to be rewarded!", objectives = "Use the Inoculating Crystal on 6 Nestlewood Owlkin. Then return to Vindicator Aldar at the Crash Site in Ammen Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37445] = { id = 37445, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Spare Parts", description = "We managed to recover a damaged holographic emitter from the crash. If we repair it, we'll have a chance to find other survivors outside of Ammen Vale.\n\nThere were devices from the ship that could be salvaged for spare parts in the area, but the local owlkin carried them off before we could get to them. \n\n{name}, you must go south to Nestlewood Thicket and Hills to find the spare parts.", progress = "When we have those spare parts, I know that we'll get this emitter repaired. With any luck there will be someone else out there left to talk to.", completion = "Let me take a look at those.\n\nYes, I think that these will do nicely; good job, {name}. The emitter is rather complex so it may take some time to finish the repairs. I'll let you know when it's ready.\n\nIn the meantime, you might see if Vindicator Aldar has anything he could use you for.", objectives = "Collect 4 Emitter Spare Parts and then return to Technician Zhanaa at the Crash Site in Ammen Vale.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37446] = { id = 37446, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lazy Peons", description = "Cursed peons! They work hard gathering lumber from the trees of the valley, but they're always taking naps! I need someone to help keep the peons in line.\n\nYou look like the right {race} for my task. Here, you take this blackjack and use it on any lazy peons you find sleeping on the job. A good smack will get them right back to work! Return the blackjack when you're done.\n\nLook for them underneath the trees in the valley. Lousy slacking peons...", progress = "No good lazy...\n\n Eh?  Do you have my blackjack?  Did you catch any peons sleeping on the job?!", completion = "Good, good.  Maybe they'll think twice before slacking next time!  Thanks for the help!", objectives = "Use the Foreman's Blackjack on 4 Lazy Peons when they're sleeping.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37447] = { id = 37447, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Blood of Demons", description = "The time has come to make contact with the Master's soul. It is somewhere in the endless expanse of the Twisting Nether. Luckily, so is Mardum.\n\nSuch a thing is not unheard of, but it will be exceedingly difficult, even here. In addition to what the matron mother had us gather, we need a great deal of demon blood.\n\nLike, a lot of it!", progress = "Once we have enough demon blood, you can begin the ritual.", completion = "If this is not enough demon blood, no amount will be. Now, let us see if we can make contact with Illidan's spirit in the Twisting Nether.", objectives = "Collect 100 Fel Blood from any demon on the Broken Isles.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37448] = { id = 37448, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "A Simple Plan", description = "Like many dreadlords, Detheroc cannot help but gloat. He was careless and I overheard many of his plans while I was held captive.\n\nWith your leave, I would like to underscore the gravity of the situation in Stormwind. The fate of Azeroth hangs in the balance.\n\nBut for all of that, I have a simple plan: get 'em.", progress = "We need to listen to Shaw's plan and then come to a consensus on the way forward.", completion = "Then, it's decided. We either expose Detheroc or it's war between the Alliance and Horde, and we lose the world to the Burning Legion.", objectives = "Hear Mathias Shaw's plan and then cast your vote.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37449] = { id = 37449, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dark Revelations", description = "I'm not going to let Cordana Felsong get away with this. There is no way in hell I am going to let that warden witch turn my people.\n\nAs for Nightglaive... I will NOT suffer a traitor to live!\n\nAre you with me, {name}?", progress = "The traitor must be killed. It is the only way.", completion = "Grim news indeed. We cannot afford the loss of even one demon hunter, but you and Kor'vas were right to put an end to Nightglaive.\n\nMore importantly, you have made a good friend in Stellagosa. The remnant of the Blue Dragonflight could prove to be a powerful ally.", objectives = "Kill Nightglaive the Traitor.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37450] = { id = 37450, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saving Stellagosa", description = "During the fighting, of all things, I saw a blue drake swoop in and attack the demons. I couldn't believe my eyes. I'd heard that the Blue Dragonflight had gone extinct.\n\nThe Legion managed to bring the drake down, but not until after she'd killed a score of them. She was magnificent. Last I saw, they were dragging her in the direction of the southern camp.\n\nWe should see if she's still alive. A dragon could prove a powerful ally.", progress = "If there's a remnant of the Blue Dragonflight nearby, we should do whatever we can to ally ourselves with them.", completion = "Beautiful creatures... pure, one with the world. I didn't think that I could hate the Legion more.\n\nThank you, {name}.", objectives = "Obtain Lykill's Key and free Stellagosa.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
quests[37451] = { id = 37451, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "See Qiana Moonshadow (Follower Mission Turn in)" }
quests[37452] = { id = 37452, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing Fate: Heap of Apexis Crystals", progress = "Twice the cost of the last, but maybe that's worth the price. Or, perhaps a different currency would be more efficient for you?  I leave the choice up to you.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I may have others.", completion = "Of course you agree." }
quests[37453] = { id = 37453, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing Fate: Mountain of Apexis Crystals", progress = "Four times the cost of the first, but only one seal.  Remember, I still offer more efficient options, but I never refuse someone who is insistent on paying me more. I leave you the choice.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I may have others.", completion = "Of course you agree." }
quests[37454] = { id = 37454, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sealing Fate: Piles of Gold", progress = "Twice the cost of the last, but maybe that's worth the price. Or, perhaps a different currency would be more efficient for you?  I leave the choice up to you.\n\nRemember, you can only obtain three seals per week.  This counts as one of those three.  Next week, I may have others.", completion = "A simple exchange with complex results.  That's the art of doing business." }
