quests[37467] = { id = 37467, flavor = "source-reference", locale = "enUS", source = "MultiLanguage retail b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceFlavor = "retail", sourceRevision = "b2e3b0bf1251f30babdb44545adf3957e94d63f6", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "The Walk of Shame", description = "The echoes of Nar'thalas still haunt me, and I cannot bear the pain of this accursed town any longer. I may still be able to get you closer to the Tidestone, however.\n\n<Farondis' eyes narrow in newfound determination.>\n\nWe will need to skirt around the edge of town. Follow me.", completion = "<The prince appears emotionally drained.>\n\nThis is the end of the road for me, {name}. I can't bear to look at them. Moreover, my mere presence puts you in danger.\n\nBeyond this point, you must walk alone.", objectives = "Escort Prince Farondis around the edge of Nar'thalas.", objectivesStatus = "corroborated by independent bundled same-flavor locale corpus" }
